1	/**
2	 * One-shot backfill script: repairs quota inflation accumulated while
3	 * recordUnpin had zero callers.
4	 *
5	 * For each NON-BYO user, diffs their pinned_cids rows against the live
6	 * Kubo pin set and deletes rows whose CID is no longer physically pinned
7	 * (phantom rows that inflated SUM(size_bytes)).
8	 *
9	 * BYO users are EXCLUDED entirely (D-09). Their advisory rows reference
10	 * CIDs that were never on CipherBox's Kubo node, so a "not on Kubo"
11	 * signal is meaningless and deleting their rows would corrupt advisory quota.
12	 *
13	 * Usage:
14	 *   ts-node scripts/backfill-pinned-cids.ts [--dry-run]
15	 *
16	 * Flags:
17	 *   --dry-run  Report candidates without deleting (safe preview mode).
18	 *              Default mode performs the actual DELETE.
19	 *
20	 * Safety guards:
21	 *   - An empty or unreachable Kubo pin set aborts with exit(1) and NO deletes.
22	 *   - --dry-run banner is printed at start so accidental runs are visible.
23	 *   - Deletes are id-scoped (WHERE id = ANY), never a blanket DELETE FROM.
24	 *   - Reuses run-migrations.ts DataSource bootstrap + secret-redacting error handler.
25	 */
26	import { DataSource } from 'typeorm';
27	import { config } from 'dotenv';
28	import {
29	  parseKuboPinLs,
30	  selectRowsToDelete,
31	  type BackfillRow,
32	} from '../apps/api/src/scripts/backfill-helpers';
33	
34	config();
35	
36	// ---------------------------------------------------------------------------
37	// Constants
38	// ---------------------------------------------------------------------------
39	
40	const BATCH_SIZE = 10;
41	const DRY_RUN = process.argv.includes('--dry-run');
42	const KUBO_API_URL = process.env.IPFS_LOCAL_API_URL ?? 'http://localhost:5001';
43	
44	// ---------------------------------------------------------------------------
45	// DataSource — mirrors run-migrations.ts bootstrap exactly
46	// ---------------------------------------------------------------------------
47	
48	const dataSource = new DataSource({
49	  type: 'postgres',
50	  host: process.env.DB_HOST ?? 'localhost',
51	  port: parseInt(process.env.DB_PORT ?? '5432', 10),
52	  username: process.env.DB_USERNAME ?? 'postgres',
53	  password: process.env.DB_PASSWORD ?? 'postgres',
54	  database: process.env.DB_DATABASE ?? 'cipherbox',
55	  entities: ['dist/**/*.entity.js'],
56	  migrations: ['dist/migrations/*.js'],
57	  logging: ['error'],
58	});
59	
60	// ---------------------------------------------------------------------------
61	// Main
62	// ---------------------------------------------------------------------------
63	
64	async function run(): Promise<void> {
65	  // Print mode banner so an operator can spot accidental destructive runs.
66	  if (DRY_RUN) {
67	    console.log('=======================================================');
68	    console.log('  MODE: DRY-RUN — no rows will be deleted');
69	    console.log('=======================================================');
70	  } else {
71	    console.log('=======================================================');
72	    console.log('  MODE: DELETE — phantom rows will be permanently deleted');
73	    console.log('=======================================================');
74	  }
75	
76	  try {
77	    await dataSource.initialize();
78	    console.log('Database connected.');
79	
80	    // -------------------------------------------------------------------
81	    // 1. Fetch the live Kubo pin set (MANDATORY GUARD: empty/unreachable aborts)
82	    // -------------------------------------------------------------------
83	    let kuboPinSet: Set<string>;
84	    try {
85	      const res = await fetch(`${KUBO_API_URL}/api/v0/pin/ls?type=recursive`, {
86	        method: 'POST',
87	      });
88	      if (!res.ok) {
89	        const errText = await res.text().catch(() => '(unreadable)');
90	        console.error(
91	          `ERROR: Kubo pin/ls returned HTTP ${res.status}: ${errText}. Aborting without deleting.`
92	        );
93	        await dataSource.destroy();
94	        process.exit(1);
95	      }
96	      const text = await res.text();
97	      kuboPinSet = parseKuboPinLs(text);
98	    } catch (fetchErr: unknown) {
99	      // Kubo unreachable — abort, never interpret as "all rows are phantoms"
100	      const msg = fetchErr instanceof Error ? fetchErr.message : String(fetchErr);
101	      console.error(
102	        `ERROR: Kubo pin/ls fetch failed (unreachable?): ${msg}. Aborting without deleting.`
103	      );
104	      await dataSource.destroy();
105	      process.exit(1);
106	    }
107	
108	    // Safety guard: an empty set means we could not enumerate real pins.
109	    // Treating it as "all CIDs absent" would wipe every non-BYO row.
110	    if (kuboPinSet.size === 0) {
111	      console.error(
112	        'ERROR: Kubo pin set is empty. Either Kubo has no pins or the parse failed. ' +
113	          'Aborting without deleting to avoid wiping all non-BYO rows.'
114	      );
115	      await dataSource.destroy();
116	      process.exit(1);
117	    }
118	    console.log(`Kubo pin set fetched: ${kuboPinSet.size} CIDs.`);
119	
120	    // -------------------------------------------------------------------
121	    // 2. Query candidate rows — non-BYO users only (D-09)
122	    //
123	    // JOIN pinned_cids to vaults on user_id = owner_id and filter
124	    // vaults.is_byo_user = false. BYO rows are excluded at query level;
125	    // selectRowsToDelete re-asserts isByoUser === false defensively.
126	    // -------------------------------------------------------------------
127	    const candidateRows = (await dataSource.query(`
128	      SELECT
129	        pc.id            AS "id",
130	        pc.user_id       AS "userId",
131	        pc.cid           AS "cid",
132	        false::boolean   AS "isByoUser"
133	      FROM pinned_cids pc
134	      JOIN vaults v ON v.owner_id = pc.user_id
135	      WHERE v.is_byo_user = false
136	    `)) as BackfillRow[];
137	
138	    console.log(`Candidate rows (non-BYO pinned_cids): ${candidateRows.length}`);
139	
140	    // -------------------------------------------------------------------
141	    // 3. Apply D-09 predicate: non-BYO rows whose CID is absent from Kubo
142	    // -------------------------------------------------------------------
143	    const rowsToDelete = selectRowsToDelete(candidateRows, kuboPinSet);
144	    console.log(`Phantom rows (absent from Kubo): ${rowsToDelete.length}`);
145	
146	    if (rowsToDelete.length === 0) {
147	      console.log('Nothing to delete. Quota is already accurate. Exiting cleanly.');
148	      await dataSource.destroy();
149	      process.exit(0);
150	    }
151	
152	    if (DRY_RUN) {
153	      // -------------------------------------------------------------------
154	      // Dry-run: report without deleting
155	      // -------------------------------------------------------------------
156	      console.log('\n--- DRY-RUN: rows that WOULD be deleted (sample up to 20) ---');
157	      const sample = rowsToDelete.slice(0, 20);
158	      for (const row of sample) {
